model_output_raw:
.TextAlignment.Center;
Font.Size(14);
Text.Font.Bold;
Text.Bold(true);
Text.Italic(true);
Text.Color("Red");
Text.Align("Center");
Text.FontFamily("Impact");
Text.Underline(true);
Text.Strikethrough(true);
Text.Overline(true);
Text.Duplicate();
Text.Resize(200);
Text.Rotate(45);
Text.Wrap(false);
Text.BackColor("Black");
Text.ForeColor("Yellow");
Text.BorderColor("White");
Text.BorderWidth(5);
Text.BorderStyle("Dashed");
Text.Shadow(true);
Text.ShadowColor("Blue");
Text.ShadowOffset(3,3);
Text.Padding(10);
Text.Margin(20);
Text.Spacing(5);
Text.Opacity(50);
Text.Transform("Rotate");
Text.Animation("FadeIn");
Text.AnimationDuration(3000);
Text.AnimationDelay(1000);
